import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']

def load(s):
    d=get_index_daily_data(s, days=4000)
    if d is None or len(d)<80: d=get_stock_daily_data(s,days=4000)
    if d is None:return None
    d=d.copy(); d['date']=pd.to_datetime(d['date']); d=d.sort_values('date').drop_duplicates('date')
    d['r']=d['close'].pct_change(); return d[['date','close','r']]
D={s:load(s) for s in U}; D={s:d for s,d in D.items() if d is not None}
# Trend consistency: 20-day signed return / 20-day absolute return, lagged one day.
rows=[]
for s,d in D.items():
    d=d.copy(); d['sig']=d['r'].rolling(20,min_periods=18).sum().shift(1)/(d['r'].abs().rolling(20,min_periods=18).sum().shift(1)+1e-12)
    d['f1']=d['close'].shift(-1)/d['close']-1
    d['f3']=d['close'].shift(-3)/d['close']-1
    d['f5']=d['close'].shift(-5)/d['close']-1
    rows.append(d.assign(symbol=s)[['date','symbol','sig','f1','f3','f5']])
x=pd.concat(rows)
def calc(col):
    vals=[]
    for dt,g in x.groupby('date'):
        g=g[["sig",col]].dropna()
        if len(g)>=8 and g['sig'].nunique()>1 and g[col].nunique()>1: vals.append(g.sig.corr(g[col],method='spearman'))
    a=np.array(vals); return len(a),float(np.nanmean(a)),float(np.nanmean(a)/(np.nanstd(a,ddof=1)+1e-12)),float(np.mean(a>0))
for c in ['f1','f3','f5']: print(c,calc(c))
# regimes and coverage / turnover
for name,lo,hi in [('2020-22','2020-01-01','2022-12-31'),('2023-25','2023-01-01','2025-12-31'),('2026-27','2026-01-01','2027-12-31'),('2028','2028-01-01','2028-12-31'),('recent120',None,None)]:
    z=x if lo is None else x[(x.date>=lo)&(x.date<=hi)]
    vals=[]
    for dt,g in z.groupby('date'):
      g=g[['sig','f1']].dropna()
      if len(g)>=8 and g.sig.nunique()>1 and g.f1.nunique()>1: vals.append(g.sig.corr(g.f1,method='spearman'))
    a=np.array(vals); print(name,len(a),round(float(np.mean(a)),6) if len(a) else None, round(float(np.mean(a)/(np.std(a,ddof=1)+1e-12)),4) if len(a)>1 else None)
# Recent 120 dates overall
allvals=[]
for dt,g in x.groupby('date'):
 g=g[['sig','f1']].dropna()
 if len(g)>=8 and g.sig.nunique()>1 and g.f1.nunique()>1: allvals.append((dt,g.sig.corr(g.f1,method='spearman')))
a=np.array([v for _,v in allvals[-120:]]); print('recent120',len(a),float(a.mean()),float(a.mean()/(a.std(ddof=1)+1e-12)))
print('rows',len(x),'dates',x.date.nunique(),'symbols',x.symbol.nunique(),'coverage',x.sig.notna().mean())
# signal artifact
x.to_csv('scripts/miner_2_20290322_trendconsistency20_signal.csv',index=False)

