D={}
for s in U:
 d=get_stock_daily_data(s,4000)
 if d is None or len(d)<300: d=get_index_daily_data(s,4000)
 if d is not None and len(d): D[s]=d.set_index('date').close.astype(float)
px=pd.DataFrame(D).sort_index().ffill(); r=np.log(px).diff()
# Downside-risk-adjusted medium momentum: 20-session return divided by
# downside deviation over the trailing 60 sessions. Signal is lagged one day.
down=r.clip(upper=0).pow(2).rolling(60).mean().pow(.5)
f=(r.rolling(20).sum()/(down*np.sqrt(20)+1e-12)).shift(1)
for h in [1,3,5,10]:
