 z=pd.Series(vals).dropna();print('h',h,'dates',len(z),'IC',z.mean(),'ICIR',z.mean()/z.std(ddof=1),'hit',(z>0).mean())
 for a,b in [('2020','2022'),('2023','2025'),('2026','2027')]:
